WITH base AS (SELECT *, CASE WHEN status_bits >= 10 THEN 'High' WHEN status_bits >= 3 THEN 'Medium' ELSE 'Low' END AS status_bits_tier FROM device_readings WHERE firmware != '2.0.1'), gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 30 MINUTES THEN 1 ELSE 0 END AS is_new_session FROM base), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT CASE WHEN session_id >= 8 THEN 'LARGE' ELSE 'SMALL' END AS session_id_tier, CASE WHEN humidity >= 80 THEN 'HIGH' ELSE 'LOW' END AS humidity_tier, SUM(CASE WHEN device_code = 'DV-01' THEN humidity ELSE 0 END) AS dv_01_humidity, AVG(status_bits) FILTER (WHERE device_code = 'DV-01') AS dv_01_avg_status_bits, BIT_OR(status_bits) AS status_bits_bit_or FROM islands GROUP BY CUBE (CASE WHEN session_id >= 8 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN humidity >= 80 THEN 'HIGH' ELSE 'LOW' END) ORDER BY humidity_tier
